#!/usr/bin/env python# -*- coding: utf-8 -*-"""Image base classes and mixins.This module provides the base classes and mixins for images."""__all__ = [    "Image",]import cv2import numpy as npfrom mon.core.pathlib import Pathfrom ..base import Data, DataLoadMixinCV2_IMREAD_FLAGS = [    cv2.IMREAD_ANYCOLOR,    cv2.IMREAD_ANYDEPTH,    cv2.IMREAD_COLOR,    cv2.IMREAD_COLOR_BGR,    cv2.IMREAD_COLOR_RGB,    cv2.IMREAD_GRAYSCALE,    cv2.IMREAD_UNCHANGED,]# ==============================================================================# TYPE DEFINITIONS & PROTOCOLS (Interfaces)# ==============================================================================# --- Type Aliases ---# --- Structural Protocols ---# ==============================================================================# BASE CLASSES & MIXINS (Behaviors)# ==============================================================================# --- Structural Bases ---# --- Lifecycle Mixins ---# --- Compute Mixins ---# ==============================================================================# CONCRETE IMPLEMENTATIONS (The Concrete Classes)# ==============================================================================# --- Primary Data Types ---class Image(Data, DataLoadMixin):    """A basic class for managing a single image.    Extend Data to handle image data and provide properties and methods related    to images.    Attributes:        _data (np.ndarray): An RGB or grayscale image, formatted as a            numpy.ndarray with dimensions (H, W, C) and pixel values ranging            from 0 to 255.        _shape (tuple[int, int, int]): Image shape as (H, W, C).        _flags (int): OpenCV flag to read the image.    """        # --- Lifecycle & Initialization ---    def __init__(        self,        data   : np.ndarray | Path,        path   : Path = None,        root   : Path = None,        flags  : int  = cv2.IMREAD_COLOR,        persist: bool = False,    ):        """Initialize a new instance.        Args:            data: Either an RGB or grayscale image, formatted as a numpy.ndarray                with dimensions (H, W, C) and pixel values ranging from 0 to 255,                or an image file path.            path: Image file path. Defaults to None.            root: Root directory of the image (of a dataset). Defaults to None.            flags: OpenCV flag to read the image. Defaults to cv2.IMREAD_COLOR.            persist: If True, persists the loaded image in memory. Defaults to False.        Raises:            TypeError: If ``data`` is neither an array nor a valid image file path.            FileNotFoundError: If the provided image file path does not exist.            ValueError: If neither ``data`` nor a valid image ``path`` is provided,                or if the provided ``flag`` is not a valid OpenCV imread flag.        """        # Validate data        shape = None        if isinstance(data, Path | str) and Path(data).is_image_file(exist=True):            path  = data            data  = None        elif isinstance(data, np.ndarray):            shape = data.shape        else:            raise TypeError(f"``data`` must be either a numpy.ndarray or a valid image file path, got {type(data)}.")                # Validate and set path        path = Path(path) if path is not None else None        root = Path(root) if root is not None else None        if data is None and path is not None:            if path.is_image_file(exist=True):                from . import io                shape = io.read_shape(path=path)            else:                raise FileNotFoundError(f"Image file not found: {path}.")                # Validate        if all(v is None for v in [data, path]):            raise ValueError("Either ``data`` or a valid image ``path`` must be provided.")                # Initialize parent classes and assign attributes        self._shape = shape        self._flags = flags        super().__init__(data=data, path=path, root=root, persist=persist)  # This will call the data setter            # --- Container / Sequence Methods ---    def __len__(self) -> int:        """Return the logical length of the container. For an image, this is always 1."""        return 1        def __getitem__(self, idx: int = 0) -> np.ndarray:        """Return the image.        Args:            idx: Index to get the image. Defaults to 0.        Returns:            The image array.        """        return self.data        # --- Properties ---    @property    def data(self) -> np.ndarray:        """Return an RGB or grayscale image, formatted as a numpy.ndarray with        dimensions (H, W, C) and pixel values ranging from 0 to 255. If it is        not persisting in memory,  call ``load()`` to load the image from disk.        """        return self._data if self._data is not None else self.load()        @property    def shape(self) -> tuple[int, int, int]:        """Return the shape of the image as (H, W, C)."""        return self._shape        @property    def imgsz(self) -> tuple[int, int]:        """Return the image size as (H, W)."""        return self.shape[0], self.shape[1]        @property    def flags(self) -> int:        """Return the OpenCV flag used to read the image."""        return self._flags        @flags.setter    def flags(self, flags: int):        """Set the OpenCV flag used to read the image.        Raises:            ValueError: If the provided flag is not a valid OpenCV imread flag.        """        if flags not in CV2_IMREAD_FLAGS:            raise ValueError(f"``flags`` must be one of {CV2_IMREAD_FLAGS}, got {flags}.")        self._flags = flags        @property    def meta(self) -> dict:        """Return metadata about the image.        Returns:            A mapping with keys such as path, root, shape, imgsz and a file hash.        """        return {            "path" : self.path,            "root" : self.root,            "shape": self.shape,            "imgsz": self.imgsz,            "hash" : self.path.stat().st_size if isinstance(self.path, Path) else None,        }        # --- Data Loading ---    def load(self, reload: bool = False) -> np.ndarray:        """Load an image from disk to memory.        Args:            reload: If True, force reloading even if data is already in memory.        Returns:            An RGB or grayscale image, formatted as a numpy.ndarray with            dimensions (H, W, C) and pixel values ranging from 0 to 255.        """        # Return the image if it is already loaded        if self._data is not None and not reload:            return self._data                # Load the image from disk        from .io import read        image = read(self.path, self._flags)                # Update the original shape of the image        if self._shape != image.shape:            self._shape = image.shape                # Cache the image if needed        if self._persist:            self._data = image        else:            self.clear()                    return image        def clear(self):        """Clear the loaded image from memory."""        if (            not self._persist            and self.path is not None            and self.path.is_image_file(exist=True)        ):                self._data = None